bool InterComms::provisioned() const { return INTER_COMMS_PROVISIONED; }

bool InterComms::settled() const { return _bootReady && elapsed(millis(), _started, SETTLE_MS); }

bool InterComms::master() const { return _leader < 0 && settled(); }

bool InterComms::ready() const { return provisioned() && _bootReady.load(); }

void InterComms::attachUi() { _uiAttached.store(true); }

void InterComms::executeAdmin(JsonObject request, JsonObject result) { admin(request, result); }

// Without the UI module, fail closed instead of exposing WLED's legacy HTTP routes.
bool InterComms::canHandle(AsyncWebServerRequest* request) { return !_uiAttached.load(); }

void InterComms::handleRequest(AsyncWebServerRequest* request) { request->send(503, "text/plain", "Install inter_comms_ui for dashboard access"); }

bool InterComms::hasExclusiveNetworkControl() const { return true; }

// Release buffered UDP packets before the Wi-Fi driver's receive-buffer owner is destroyed.
void InterComms::onNetworkReset() { _udp.stop(); _socketReady = false; _radio.stop(); }

// Give LAN association a normal startup window, then hold/search channels for the direct link.
uint8_t InterComms::getWiFiChannelRequest() const {
  if (!ready() || !_radio.ready() || WiFi.status() == WL_CONNECTED || forceReconnect) return 0;
  bool gateway = WiFi.softAPgetStationNum() > 0;
  for (const auto& peer : _peers) if (peer.live(millis()) && peer.canLead && peer.gatewayScore > 0) gateway = true;
  if (!InterCommsRadio::channelWindow(millis(), _lastLan ? _lastLan : _started, gateway)) return 0;
  return _radioChannel;
}

// Register before stock WLED handlers; this catch-all prevents plaintext control and file/OTA bypasses.
void InterComms::setup() {
  _radio.begin();
  strlcpy(_buildId, toHex(esp_app_get_description()->app_elf_sha256, BUILD_ID_BYTES).c_str(), sizeof(_buildId));
  _idValid = esp_read_mac(_id, ESP_MAC_WIFI_STA) == ESP_OK;
  mbedtls_sha256_init(&_firmware.sha); mbedtls_sha256_init(&_uploadSha);
  server.addHandler(this);
  receiveDirect = false; receiveGroups = 0; sendNotificationsRT = false;
#ifndef WLED_DISABLE_MQTT
  mqttEnabled = false;
#endif
#ifndef WLED_DISABLE_ALEXA
  alexaEnabled = false;
#endif
#ifndef WLED_DISABLE_HUESYNC
  huePollingEnabled = false;
#endif
#ifndef WLED_DISABLE_ESPNOW
  enableESPNow = false; useESPNowSync = false;
#endif
#ifdef WLED_ENABLE_AOTA
  aOtaEnabled = false;
#endif
}

// Create one boot epoch and send key after Wi-Fi exists; retry a failed initialization on the next loop.
bool InterComms::initializeSession() {
  if (!_bootReady) {
    if (WiFi.getMode() == WIFI_MODE_NULL) return false;
    esp_fill_random(_boot, 16);
    if (!deriveKey(_id, _boot, _sendKey)) return false;
    _bootReady = true;
    _started = millis();
    _commandId = esp_random();
  }
  return true;
}

// Keep transport, cryptography, settings, and OTA work serialized on the firmware main loop.
// Run admission and election before lighting synchronization, then service bounded update work.
void InterComms::loop() {
  if (!_lightingRestored) restoreLighting();
  persistLighting();
  if (!provisioned() || !_idValid || !initializeSession()) return;

  bool connected = WiFi.status() == WL_CONNECTED;
  serviceNetwork(connected);

  uint32_t now = millis();
  updateRadioChannel(now, connected);
  updateLeader(now);

  if ((_socketReady || _radio.ready()) && elapsed(millis(), _lastHello, HEARTBEAT_MS)) {
    heartbeat();
    _lastHello = millis();
  }
  if (_socketReady || _radio.ready()) synchronize();
  servicePreparation();
  serviceTransfers();
  serviceAutomaticUpdates();
}

